  "logic": "class Component extends DCLogic {\n  pillar() {\n    const PILLARS = {\n      marketing: { bg: \"#FFCC00\", name: \"#ffffff\", logo: \"#060228\" },\n      jump:      { bg: \"#49FF9F\", name: \"#060228\", logo: \"#060228\" },\n      content:   { bg: \"#00FFE6\", name: \"#060228\", logo: \"#060228\" },\n      productie: { bg: \"#FC06E5\", name: \"#ffffff\", logo: \"#060228\" },\n      standaard: { bg: \"#3D5AFE\", name: \"#ffffff\", logo: \"#ffffff\" },\n      navy:      { bg: \"#060228\", name: \"#ffffff\", logo: \"#ffffff\" },\n    };\n    return PILLARS[this.props.pillar] || PILLARS.marketing;\n  }\n  applyVars() {\n    const p = this.pillar(), r = window.__bytRoot.style;\n    r.setProperty(\"--bg\", p.bg); r.setProperty(\"--name\", p.name); r.setProperty(\"--logo\", p.logo);\n  }\n  componentDidMount() { this.applyVars(); }\n  componentDidUpdate() { this.applyVars(); }\n  renderVals() {\n    return {\n      name: this.props.name ?? \"Tim Roescher\",\n      role: this.props.role ?? \"Marketing\",\n    };\n  }\n}",
