  "logic": "class Component extends DCLogic {\n  pillar() {\n    const PILLARS = {\n      navy:      { bg: \"#060228\", text: \"#ffffff\", accent: \"#3D5AFE\", logo: \"#ffffff\" },\n      standaard: { bg: \"#3D5AFE\", text: \"#ffffff\", accent: \"#060228\", logo: \"#ffffff\" },\n      jump:      { bg: \"#49FF9F\", text: \"#060228\", accent: \"#2F7E4D\", logo: \"#060228\" },\n      marketing: { bg: \"#FFCC00\", text: \"#060228\", accent: \"#C25100\", logo: \"#060228\" },\n      content:   { bg: \"#00FFE6\", text: \"#060228\", accent: \"#008B8B\", logo: \"#060228\" },\n      productie: { bg: \"#FC06E5\", text: \"#060228\", accent: \"#7B1FA2\", logo: \"#060228\" },\n    };\n    return PILLARS[this.props.pillar] || PILLARS.navy;\n  }\n  applyVars() {\n    const p = this.pillar(), onLight = p.text === \"#060228\", r = window.__bytRoot.style;\n    const h = parseInt(this.props.homeScore ?? \"28\", 10);\n    const a = parseInt(this.props.awayScore ?? \"24\", 10);\n    const win = \"#3D5AFE\", lose = \"#060228\";\n    r.setProperty(\"--bg\", p.bg);\n    r.setProperty(\"--accent\", p.accent);\n    r.setProperty(\"--logo\", p.logo);\n    r.setProperty(\"--mark\", onLight ? \"#060228\" : \"#ffffff\");\n    r.setProperty(\"--pill-bg\", onLight ? \"rgba(6,2,40,.12)\" : \"rgba(255,255,255,.16)\");\n    r.setProperty(\"--pill-text\", p.text);\n    r.setProperty(\"--home-color\", h >= a ? win : lose);\n    r.setProperty(\"--away-color\", a >= h ? win : lose);\n  }\n  componentDidMount() { this.applyVars(); }\n  componentDidUpdate() { this.applyVars(); }\n  renderVals() {\n    return {\n      competition: this.props.competition ?? \"Super Handball League\",\n      homeTeam: this.props.homeTeam ?? \"Lions\",\n      awayTeam: this.props.awayTeam ?? \"Bulgarije\",\n      homeScore: this.props.homeScore ?? \"28\",\n      awayScore: this.props.awayScore ?? \"24\",\n      platform: this.props.platform ?? \"JUMP\",\n    };\n  }\n}",
