  "logic": "class Component extends DCLogic {\n  pillar() {\n    const PILLARS = {\n      standaard: { accent: \"#3D5AFE\", text: \"#ffffff\" },\n      jump:      { accent: \"#49FF9F\", text: \"#060228\" },\n      marketing: { accent: \"#FFCC00\", text: \"#060228\" },\n      content:   { accent: \"#00FFE6\", text: \"#060228\" },\n      productie: { accent: \"#FC06E5\", text: \"#060228\" },\n    };\n    return PILLARS[this.props.pillar] || PILLARS.standaard;\n  }\n  applyVars() {\n    const p = this.pillar(), r = window.__bytRoot.style;\n    r.setProperty(\"--accent\", p.accent);\n    r.setProperty(\"--accent-text\", p.text);\n  }\n  componentDidMount() { this.applyVars(); }\n  componentDidUpdate() { this.applyVars(); }\n  renderVals() {\n    return {\n      eyebrow: this.props.eyebrow ?? \"JUMP ORIGINALS\",\n      title: this.props.title ?? \"Van Veenendaal naar de top\",\n      duration: this.props.duration ?? \"12:34\",\n    };\n  }\n}",
